(5224022, 760294, 54446, '<td valign="top">Gorgeous scene.  Very wonderful light.  I think this is a good representation of silence.  There is nothing more silent than the high country wilderness.  (When the wind is not blowing.)  My fav in this challenge.  Hope it ribbons!  10</td>', 'Gorgeous scene.  Very wonderful light.  I think this is a good representation of silence.  There is nothing more silent than the high country wilderness.  (When the wind is not blowing.)  My fav in this challenge.  Hope it ribbons!  10', '2009-01-28 10:17:24.000000', NULL, 1),
(5224027, 759792, 54446, '<td valign="top">I think it silent on the bottom.  Pretty good image.  9</td>', 'I think it silent on the bottom.  Pretty good image.  9', '2009-01-28 10:18:25.000000', NULL, 1),
(5224029, 760370, 54446, '<td valign="top">Great colors. Pleasant peaceful scene.  This does say silent to me.  9</td>', 'Great colors. Pleasant peaceful scene.  This does say silent to me.  9', '2009-01-28 10:19:03.000000', NULL, 1),
(5224033, 760451, 54446, '<td valign="top">Good idea and well executed and presented.  This should do well.  In this case, softness is silence.  Great composition and eye pleasing exposure.</td>', 'Good idea and well executed and presented.  This should do well.  In this case, softness is silence.  Great composition and eye pleasing exposure.', '2009-01-28 10:20:31.000000', NULL, 1);
