(5224132, 759407, 84363, '<td valign="top">I don''t see a fork and your whites are over-exposed</td>', 'I don''t see a fork and your whites are over-exposed', '2009-01-28 11:03:09.000000', NULL, 1),
(5224134, 760043, 84363, '<td valign="top">There''s a lot of gray and midtones.  Would like to see more contrast</td>', 'There''s a lot of gray and midtones.  Would like to see more contrast', '2009-01-28 11:03:55.000000', NULL, 1),
(5224135, 760134, 84363, '<td valign="top">Was this taken at night with a flash?  The processing seems totally off</td>', 'Was this taken at night with a flash?  The processing seems totally off', '2009-01-28 11:04:42.000000', NULL, 1),
(5224141, 759908, 84363, '<td valign="top">IMO I think this would fit better in the Sound challenge</td>', 'IMO I think this would fit better in the Sound challenge', '2009-01-28 11:06:37.000000', NULL, 1),
(5224143, 760123, 84363, '<td valign="top">To much gray and not enough contrast</td>', 'To much gray and not enough contrast', '2009-01-28 11:07:23.000000', NULL, 1),
(5224144, 760388, 54446, '<td valign="top">Did you place this in the correct challenge?  I like the image.  Taken from an airplane, I assume.  Jet engines are one of the loudest things I can imagine, even from many miles away.  Bumping this up on review, and fresh eyes context.  8</td>', 'Did you place this in the correct challenge?  I like the image.  Taken from an airplane, I assume.  Jet engines are one of the loudest things I can imagine, even from many miles away.  Bumping this up on review, and fresh eyes context.  8', '2009-01-28 11:07:25.000000', NULL, 1),
(5224147, 760342, 84363, '<td valign="top">Great picture.  However, my eye is immediatley drawn to the over exposed whites in the cloud above the tree.</td>', 'Great picture.  However, my eye is immediatley drawn to the over exposed whites in the cloud above the tree.', '2009-01-28 11:08:32.000000', NULL, 1),
