(5225188, 760237, 96881, '<td valign="top">I can''t seem to find the point of focus of this image.  I feel there is too much foreground and the trees are then cropped out</td>', 'I can''t seem to find the point of focus of this image.  I feel there is too much foreground and the trees are then cropped out', '2009-01-28 21:16:35.000000', NULL, 1),
(5225191, 760034, 96881, '<td valign="top">There are a number of the same type of image submitted.  The harsh lighting in this really hurts the image.</td>', 'There are a number of the same type of image submitted.  The harsh lighting in this really hurts the image.', '2009-01-28 21:17:56.000000', NULL, 1),
(5225200, 760128, 101322, '<td valign="top">I really like the composition of this photo and the selective colouring of the horse really draws the eye.</td>', 'I really like the composition of this photo and the selective colouring of the horse really draws the eye.', '2009-01-28 21:29:18.000000', NULL, 1),
(5225203, 760221, 96751, '<td valign="top">Wow!  Very powerful shot.  Great use of grainy contrast.</td>', 'Wow!  Very powerful shot.  Great use of grainy contrast.', '2009-01-28 21:31:53.000000', NULL, 1),
(5225206, 758716, 96751, '<td valign="top">This shot grew on me.  I keep coming back to it.  Nice tones, and dof.  Very sharp dashboard.</td>', 'This shot grew on me.  I keep coming back to it.  Nice tones, and dof.  Very sharp dashboard.', '2009-01-28 21:33:03.000000', NULL, 1),
