(5225269, 760167, 82690, '<td valign="top">Love the photo, don''t know if I quite get the title though</td>', 'Love the photo, don''t know if I quite get the title though', '2009-01-28 21:56:30.000000', NULL, 1),
(5225270, 760385, 82690, '<td valign="top">IDK bout this one, she''s sitting there seeming as if she would be listening to all of everything that seems to be surrounding her; however, she''s listening to her ipod... hmm</td>', 'IDK bout this one, she''s sitting there seeming as if she would be listening to all of everything that seems to be surrounding her; however, she''s listening to her ipod... hmm', '2009-01-28 21:58:11.000000', NULL, 1),
