INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5225277, 760370, 101838, '<td valign="top">Very nice colors, but I''d make a much wider capture. It feels too tight for this challenge - needs more empty space.</td>', 'Very nice colors, but I''d make a much wider capture. It feels too tight for this challenge - needs more empty space.', '2009-01-28 22:03:03.000000', NULL, 1),
(5225293, 759719, 101838, '<td valign="top">I''d prefer to see an empty street with dim lights</td>', 'I''d prefer to see an empty street with dim lights', '2009-01-28 22:11:08.000000', NULL, 1),
(5225314, 760404, 102362, '<td valign="top">interesting...</td>', 'interesting...', '2009-01-28 22:21:27.000000', NULL, 1),
(5225315, 760294, 101838, '<td valign="top">But for those dark edges in the front and especially  black right corner (which IMHO, all should have been cropped out) it would be excellent. With them it''s just good.</td>', 'But for those dark edges in the front and especially  black right corner (which IMHO, all should have been cropped out) it would be excellent. With them it''s just good.', '2009-01-28 22:21:39.000000', NULL, 1),
(5225328, 759215, 96751, '<td valign="top">Nice concept, but very flat.</td>', 'Nice concept, but very flat.', '2009-01-28 22:27:15.000000', NULL, 1),
(5225331, 760285, 96751, '<td valign="top">LOL!  I think if the light source had been a little higher, the ear would have shown better.  Nice detail though.</td>', 'LOL!  I think if the light source had been a little higher, the ear would have shown better.  Nice detail though.', '2009-01-28 22:27:54.000000', NULL, 1),
(5225333, 759452, 96751, '<td valign="top">Soooo sweet.  But I hear purring....  Does the kitty have a nipped ear or is that overblown lighting?</td>', 'Soooo sweet.  But I hear purring....  Does the kitty have a nipped ear or is that overblown lighting?', '2009-01-28 22:29:36.000000', NULL, 1),
(5225336, 760433, 96751, '<td valign="top">I so want to love it but there''s just not enough depth here.  Just a tiny bit more contrast would have helped.</td>', 'I so want to love it but there''s just not enough depth here.  Just a tiny bit more contrast would have helped.', '2009-01-28 22:30:13.000000', NULL, 1),
(5225340, 760388, 96751, '<td valign="top">Nice feeling here.  Very strong contrast, nice tones.  Contrail detail is great.  Just wish the plane silhouette was over a brighter spot...</td>', 'Nice feeling here.  Very strong contrast, nice tones.  Contrail detail is great.  Just wish the plane silhouette was over a brighter spot...', '2009-01-28 22:31:55.000000', NULL, 1),
(5225343, 760367, 96751, '<td valign="top">Hmmmm....  The slight tilt in the horizon doesn''t work for me.  Also, the light/tone on the t-shirt is too similar to the water and sort of blends in.  There is a lack of depth in this otherwise very tranquil shot.</td>', 'Hmmmm....  The slight tilt in the horizon doesn''t work for me.  Also, the light/tone on the t-shirt is too similar to the water and sort of blends in.  There is a lack of depth in this otherwise very tranquil shot.', '2009-01-28 22:33:24.000000', NULL, 1),
(5225347, 760128, 96751, '<td valign="top">I wish the pony could have been more isolated.  The bench, path, and black patch above it are just too distracting.</td>', 'I wish the pony could have been more isolated.  The bench, path, and black patch above it are just too distracting.', '2009-01-28 22:34:09.000000', NULL, 1),
(5225350, 760294, 96751, '<td valign="top">Front page, if not a winner.  I sure hope you didn''t climb up here just for the challenge :-)  Incredible depth and detail, deliciously soft tones and crisp textures.  Love the sun beams.  My fave so far.</td>', 'Front page, if not a winner.  I sure hope you didn''t climb up here just for the challenge :-)  Incredible depth and detail, deliciously soft tones and crisp textures.  Love the sun beams.  My fave so far.', '2009-01-28 22:35:25.000000', NULL, 1),
(5225351, 759832, 96751, '<td valign="top">My vote for funniest shot.  Why, oh why, did you not clone out that speck on the nose????  Background is a little blown out, so it flattens the image a bit.</td>', 'My vote for funniest shot.  Why, oh why, did you not clone out that speck on the nose????  Background is a little blown out, so it flattens the image a bit.', '2009-01-28 22:36:18.000000', NULL, 1),
