(5225353, 760421, 25313, '<td valign="top">certainly better than a tape job. very expressive. could have a better focus.</td>', 'certainly better than a tape job. very expressive. could have a better focus.', '2009-01-28 22:38:48.000000', NULL, 1),
(5225354, 759524, 89468, '<td valign="top">These are beautiful trees and the color of the sky is very very interesting. However, the snow does not work for me.</td>', 'These are beautiful trees and the color of the sky is very very interesting. However, the snow does not work for me.', '2009-01-28 22:39:29.000000', NULL, 1),
