(5226351, 758435, 5364, '<td valign="top">Nice piece of lateral thinking, but the mute button is a bit lost amongst the other buttons - maybe if you could have found a way to have the mute stand out by using another light shining just on that button?</td>', 'Nice piece of lateral thinking, but the mute button is a bit lost amongst the other buttons - maybe if you could have found a way to have the mute stand out by using another light shining just on that button?', '2009-01-29 16:54:53.000000', NULL, 1),
(5226352, 758406, 5364, '<td valign="top">I have to say that it makes me imagine the other players that you''ve cropped off, making lots of noise. As an image I find it a bit too unsharp.</td>', 'I have to say that it makes me imagine the other players that you''ve cropped off, making lots of noise. As an image I find it a bit too unsharp.', '2009-01-29 16:58:08.000000', NULL, 1),
(5226358, 759319, 5364, '<td valign="top">Your subject has the potential to invoke the desired feeling of silence, but the composition isn''t very interesting as the empty space in the foreground is just a distraction.</td>', 'Your subject has the potential to invoke the desired feeling of silence, but the composition isn''t very interesting as the empty space in the foreground is just a distraction.', '2009-01-29 17:00:38.000000', NULL, 1),
(5226363, 760016, 5364, '<td valign="top">Your composition doesn''t do much for me as I don''t think including the pond has added anything to the image. The thought that came to me was getting closer to the statue - you''ve got a "silent scream" with the right hand figure.</td>', 'Your composition doesn''t do much for me as I don''t think including the pond has added anything to the image. The thought that came to me was getting closer to the statue - you''ve got a "silent scream" with the right hand figure.', '2009-01-29 17:04:15.000000', NULL, 1),
(5226371, 759539, 5364, '<td valign="top">A good choice of subject, and going mono was the right choice, but the "jaunty" angle isn''t helping get me in the silent mood.</td>', 'A good choice of subject, and going mono was the right choice, but the "jaunty" angle isn''t helping get me in the silent mood.', '2009-01-29 17:12:23.000000', NULL, 1),
(5226401, 759640, 101824, '<td valign="top">the dots add so much... they make the picture much more interesting... lovely shot...</td>', 'the dots add so much... they make the picture much more interesting... lovely shot...', '2009-01-29 17:45:46.000000', NULL, 1),
(5226421, 760341, 101682, '<td valign="top">Nice way to draw the eye to the backboard.</td>', 'Nice way to draw the eye to the backboard.', '2009-01-29 18:05:18.000000', NULL, 1),
