(5226906, 758414, 47294, '<td valign="top">Wow, I''d love to visit this location.  Great exposure. Good luck 8</td>', 'Wow, I''d love to visit this location.  Great exposure. Good luck 8', '2009-01-29 23:48:16.000000', NULL, 1),
