(5227047, 759063, 58415, '<td valign="top">ouch!!great shot, i can really hear the sound looking at the picture</td>', 'ouch!!great shot, i can really hear the sound looking at the picture', '2009-01-30 05:58:54.000000', NULL, 1),
(5227059, 759832, 98026, '<td valign="top">Very cute picture. Nice take on the theme</td>', 'Very cute picture. Nice take on the theme', '2009-01-30 06:50:43.000000', NULL, 1),
(5227060, 758509, 98026, '<td valign="top">I really like the concept here &amp; think that the execution is good. But I do get the feeling that creating a sense of movement may have helped.</td>', 'I really like the concept here & think that the execution is good. But I do get the feeling that creating a sense of movement may have helped.', '2009-01-30 06:54:56.000000', NULL, 1),
(5227062, 760435, 98026, '<td valign="top">Really nice portrait. I like the composition &amp; the emotion conveyed by the models face is amazing. Nice work (I''m sure this photo will do well)</td>', 'Really nice portrait. I like the composition & the emotion conveyed by the models face is amazing. Nice work (I''m sure this photo will do well)', '2009-01-30 06:57:22.000000', NULL, 1),
(5227063, 760264, 98026, '<td valign="top">There is something slightly disturbing about this image. The stubbby fingers of the hand contrast with the beautiful feminine blue eye.</td>', 'There is something slightly disturbing about this image. The stubbby fingers of the hand contrast with the beautiful feminine blue eye.', '2009-01-30 07:03:01.000000', NULL, 1),
(5227065, 759640, 98026, '<td valign="top">Very nice image. I did find the holes (?) in the wall to be slightly distracting (they almost look like full stops to the unspoken exhortation for silence)</td>', 'Very nice image. I did find the holes (?) in the wall to be slightly distracting (they almost look like full stops to the unspoken exhortation for silence)', '2009-01-30 07:05:41.000000', NULL, 1),
(5227069, 759318, 98026, '<td valign="top">IMHO this image (as beautiful as it is) does not strictly represent "silence" per se. I feel as though it is a very well composed landscape - that could easily fit more comfortably into a dozen other catagories. I note however, have found that my voting in this challenge has tended to be skewed towards clever and interesting "concepts" more than the quality of the images themselves.</td>', 'IMHO this image (as beautiful as it is) does not strictly represent "silence" per se. I feel as though it is a very well composed landscape - that could easily fit more comfortably into a dozen other catagories. I note however, have found that my voting in this challenge has tended to be skewed towards clever and interesting "concepts" more than the quality of the images themselves.', '2009-01-30 07:13:13.000000', NULL, 1),
(5227070, 758656, 98026, '<td valign="top">Beautiful image. I like what this image represents - the absence of water screams "silence" to me in a very clever, subtle way (can you subtly scream??).<br/> <br/>It is what is not in the image that so cleverly elevates this image out of the run of the mill.</td>', 'Beautiful image. I like what this image represents - the absence of water screams "silence" to me in a very clever, subtle way (can you subtly scream??). It is what is not in the image that so cleverly elevates this image out of the run of the mill.', '2009-01-30 07:19:21.000000', NULL, 1),
(5227071, 760036, 98026, '<td valign="top">This is one of the very few images I have seen in this challenge that has actually succeeded in conveying the silence of a deserted space. I put this down to the excellent use of light and the mono conversion. Well done.</td>', 'This is one of the very few images I have seen in this challenge that has actually succeeded in conveying the silence of a deserted space. I put this down to the excellent use of light and the mono conversion. Well done.', '2009-01-30 07:22:06.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5227074, 760128, 98026, '<td valign="top">I like the images that have attempted to convey the sense of silence - not by what is included in the image but by what is excluded. I think this image does this really well. A tighter crop - with just the horse and the seat might also have been as effective. Well done.</td>', 'I like the images that have attempted to convey the sense of silence - not by what is included in the image but by what is excluded. I think this image does this really well. A tighter crop - with just the horse and the seat might also have been as effective. Well done.', '2009-01-30 07:25:32.000000', NULL, 1),
(5227075, 759738, 98026, '<td valign="top">The lighting in this image is first class &amp; the solemnity of the location conveys silence beautifully.</td>', 'The lighting in this image is first class & the solemnity of the location conveys silence beautifully.', '2009-01-30 07:27:36.000000', NULL, 1),
(5227078, 760122, 98026, '<td valign="top">Someone once said that "assassination is the most extreme form of censorship" - I guess this image fits in with that theme. I might be wrong but there does seem to be a bit of a blown highlight on the left side of the noose. Nice concept though - original but germane to the theme.</td>', 'Someone once said that "assassination is the most extreme form of censorship" - I guess this image fits in with that theme. I might be wrong but there does seem to be a bit of a blown highlight on the left side of the noose. Nice concept though - original but germane to the theme.', '2009-01-30 07:31:44.000000', NULL, 1),
(5227080, 760356, 98026, '<td valign="top">I think this image captures a sense of personal reflection (the spiritual kind not the water). But I also think that the same effect could have been achieved with a closer crop (perhaps omitting some of the trees).</td>', 'I think this image captures a sense of personal reflection (the spiritual kind not the water). But I also think that the same effect could have been achieved with a closer crop (perhaps omitting some of the trees).', '2009-01-30 07:35:40.000000', NULL, 1),
(5227082, 760221, 98026, '<td valign="top">A great concept. The right to silence is so obvious (now) &amp; yet you have communicated it beautifully.</td>', 'A great concept. The right to silence is so obvious (now) & yet you have communicated it beautifully.', '2009-01-30 07:38:07.000000', NULL, 1),
(5227276, 759909, 98186, '<td valign="top">I like the picture and the concept.  I feel like something should be different.  Maybe the subject should be a little more off center, or the shot should be more close up.  I like it, but I don''t love it.</td>', 'I like the picture and the concept.  I feel like something should be different.  Maybe the subject should be a little more off center, or the shot should be more close up.  I like it, but I don''t love it.', '2009-01-30 11:30:17.000000', NULL, 1),
(5227279, 759791, 98186, '<td valign="top">I love that early morning lake fog.  Its special to see, and even more special to capture on film.  Awesome!</td>', 'I love that early morning lake fog.  Its special to see, and even more special to capture on film.  Awesome!', '2009-01-30 11:31:16.000000', NULL, 1),
(5227287, 760422, 98186, '<td valign="top">I don''t know where you shot this, but it looks well removed from civilization.  I appreciate the hike that you probably took to get this picture.</td>', 'I don''t know where you shot this, but it looks well removed from civilization.  I appreciate the hike that you probably took to get this picture.', '2009-01-30 11:36:56.000000', NULL, 1),
(5227292, 760044, 98186, '<td valign="top">What a rare shot!  Very cool!</td>', 'What a rare shot!  Very cool!', '2009-01-30 11:38:07.000000', NULL, 1),
(5227426, 760442, 59029, '<td valign="top">I like the use of what seems to be a dark sepia filter to add to the sense of an old photo; the tree is a great subject and both setting and light are pleasingly eerie and emotive.<br/>However, this does look like an outtake from Single Tree.  The tree dominates the shot; the swing is secondary, you have to look for it and most of the dpc populace like to see details like that front and centre, for it is the swing hanging from the tree evoking the nostalgia. I am not a huge fan of borders, and here the double border accentuate a very tight crop, which is probably what is hurting your score the most.<br/>If this were my shot, I''d''ve used the wonderful shape, esp the curve of the trunk, and of the tree limbs over and around the swing to frame it.  My vote would probably have been 5.<br/>Hope this helps! :-)</td>', 'I like the use of what seems to be a dark sepia filter to add to the sense of an old photo; the tree is a great subject and both setting and light are pleasingly eerie and emotive.However, this does look like an outtake from Single Tree.  The tree dominates the shot; the swing is secondary, you have to look for it and most of the dpc populace like to see details like that front and centre, for it is the swing hanging from the tree evoking the nostalgia. I am not a huge fan of borders, and here the double border accentuate a very tight crop, which is probably what is hurting your score the most.If this were my shot, I''d''ve used the wonderful shape, esp the curve of the trunk, and of the tree limbs over and around the swing to frame it.  My vote would probably have been 5.Hope this helps! :-)', '2009-01-30 13:43:05.000000', NULL, 1),
(5227434, 760223, 91527, '<td valign="top">Hello hello!  Sorry it took me so long to get around to this :)  <br/> <br/>I really liked this photo when I went through them...the depth of field is really really nice, and I love how sharp the cat is.  The colors are lovely and calming, and the exposure is good.<br/> <br/>I think the only real problems with this shot are the distracting background on the right and the fact that half the cat is cut off.<br/> <br/>This would probably have been around a 6 had I been voting.  If the background wasn''t distracting and the cat wasn''t cut off, it would have been a 7 or an 8.<br/> <br/>Hope I helped!!  :)</td>', 'Hello hello!  Sorry it took me so long to get around to this :)   I really liked this photo when I went through them...the depth of field is really really nice, and I love how sharp the cat is.  The colors are lovely and calming, and the exposure is good. I think the only real problems with this shot are the distracting background on the right and the fact that half the cat is cut off. This would probably have been around a 6 had I been voting.  If the background wasn''t distracting and the cat wasn''t cut off, it would have been a 7 or an 8. Hope I helped!!  :)', '2009-01-30 13:49:50.000000', NULL, 1),
(5227441, 760363, 59029, '<td valign="top">I like this picture a lot.  The b/w works well, use of thirds is good, whited-out b/g draws attention to him, and the snow on his hair and clothing makes it look like he''s coming forward out of the b/g, so gives it a sense of story.  The lighting is good, no glare-y areas that I can see.  There is a sense of expectancy in his eyes and his lips are parted just right...any more open and he would appear to be about to speak, but fully closed could make his face look tense.<br/>The main criticque here is the tight-ish crop at the top of his head.  The b/g may turn off some of the purists here, but I like it.<br/>I have a confession to make...I don''t yet know how to do keyboard voting so until a fellow dpcer enlightens me, I am leaving *real* scores for now, which sadly I will have to change to avoid accusations of friend voting.  This cute guy gets a 7.</td>', 'I like this picture a lot.  The b/w works well, use of thirds is good, whited-out b/g draws attention to him, and the snow on his hair and clothing makes it look like he''s coming forward out of the b/g, so gives it a sense of story.  The lighting is good, no glare-y areas that I can see.  There is a sense of expectancy in his eyes and his lips are parted just right...any more open and he would appear to be about to speak, but fully closed could make his face look tense.The main criticque here is the tight-ish crop at the top of his head.  The b/g may turn off some of the purists here, but I like it.I have a confession to make...I don''t yet know how to do keyboard voting so until a fellow dpcer enlightens me, I am leaving *real* scores for now, which sadly I will have to change to avoid accusations of friend voting.  This cute guy gets a 7.', '2009-01-30 13:58:12.000000', NULL, 1),
(5227529, 760044, 38198, '<td valign="top">Is this the same as the tree?</td>', 'Is this the same as the tree?', '2009-01-30 14:36:09.000000', NULL, 1),
(5227537, 759709, 38198, '<td valign="top">Cute cat and very good photo I wish this was a pet challenge not sure it is silence hard one to photograph but I do so love this photo (if in pet it would be a 10) so what the heck- good photo and did anyone else photograph silence 10!</td>', 'Cute cat and very good photo I wish this was a pet challenge not sure it is silence hard one to photograph but I do so love this photo (if in pet it would be a 10) so what the heck- good photo and did anyone else photograph silence 10!', '2009-01-30 14:40:05.000000', NULL, 1),
(5227541, 760243, 38198, '<td valign="top">Make it bigger next time. Nice photo love the color.</td>', 'Make it bigger next time. Nice photo love the color.', '2009-01-30 14:41:09.000000', NULL, 1),
