(5228353, 760179, 85866, '<td valign="top">My first reaction was to criticise some aspects of this image ... but I was quickly drawn to her eyes, compelling me to keep silent over these niggles ... it''s an great image that really holds you!</td>', 'My first reaction was to criticise some aspects of this image ... but I was quickly drawn to her eyes, compelling me to keep silent over these niggles ... it''s an great image that really holds you!', '2009-01-31 02:48:00.000000', NULL, 1),
(5228370, 760300, 5364, '<td valign="top">I can see that inside the bridge would be an oasis of quiet in the noisy city, but to convey that in a more immediate way I think you needed to be inside looking out.</td>', 'I can see that inside the bridge would be an oasis of quiet in the noisy city, but to convey that in a more immediate way I think you needed to be inside looking out.', '2009-01-31 03:46:31.000000', NULL, 1),
