(5231465, 759560, 99263, '<td valign="top">Nice landscape image and nice reflections and it conveys silence. It might have done so even more powerfully if you chosen a horizontal crop and presented a more panoramic view. 5</td>', 'Nice landscape image and nice reflections and it conveys silence. It might have done so even more powerfully if you chosen a horizontal crop and presented a more panoramic view. 5', '2009-02-01 10:30:18.000000', NULL, 1),
(5231466, 760177, 99263, '<td valign="top">I remember that model. We used to have one way back too. But I remember that although they were silent movies the machine itself was not silent at all and made quite a whirring noise when running. But still..it does convey the concept of silence for this challenge. 5</td>', 'I remember that model. We used to have one way back too. But I remember that although they were silent movies the machine itself was not silent at all and made quite a whirring noise when running. But still..it does convey the concept of silence for this challenge. 5', '2009-02-01 10:30:23.000000', NULL, 1),
(5231467, 760418, 99263, '<td valign="top">Nice composition,nice detail and good tones but it does not convey to me a feeling of silence. 5</td>', 'Nice composition,nice detail and good tones but it does not convey to me a feeling of silence. 5', '2009-02-01 10:30:28.000000', NULL, 1),
(5231468, 760223, 99263, '<td valign="top">WOW! Stunning brilliant image. Sure to finish in the top 10. Fits the challenge perfectly. I can feel the silence. Super composition. Lovely cat.<br/><br/><i>Message edited by author 2009-02-05 02:59:41.</i></td>', 'WOW! Stunning brilliant image. Sure to finish in the top 10. Fits the challenge perfectly. I can feel the silence. Super composition. Lovely cat.', '2009-02-01 10:30:35.000000', '2009-02-05 02:59:41.000000', 1),
