(5231981, 758509, 5364, '<td valign="top">Excellent technically, but because you''ve presented "pin-sharp" as it were, it doesn''t look like it''s been dropped</td>', 'Excellent technically, but because you''ve presented "pin-sharp" as it were, it doesn''t look like it''s been dropped', '2009-02-01 13:09:11.000000', NULL, 1),
(5231990, 760369, 5364, '<td valign="top">For my tastes you could have increased the contrast to get the blacks blacker, and levelled the horizon so it didn''t slope down to the right.</td>', 'For my tastes you could have increased the contrast to get the blacks blacker, and levelled the horizon so it didn''t slope down to the right.', '2009-02-01 13:12:07.000000', NULL, 1),
(5232004, 760235, 5364, '<td valign="top">I can see what you''re trying to convey, but chopping the tree off like this leads my eye downward out of the image.</td>', 'I can see what you''re trying to convey, but chopping the tree off like this leads my eye downward out of the image.', '2009-02-01 13:17:26.000000', NULL, 1),
(5232039, 760417, 5364, '<td valign="top">Seems a bit lop-sided with the empty space on the left hand side and unfortunately my first impression was that she''s trying to put her finger up her nose! Otherwise it''s a good image.</td>', 'Seems a bit lop-sided with the empty space on the left hand side and unfortunately my first impression was that she''s trying to put her finger up her nose! Otherwise it''s a good image.', '2009-02-01 13:28:36.000000', NULL, 1),
(5232056, 759837, 5364, '<td valign="top">Good image, but I find the border rather intrusive</td>', 'Good image, but I find the border rather intrusive', '2009-02-01 13:36:03.000000', NULL, 1),
(5232081, 759518, 5364, '<td valign="top">This had the potential to be a wonderfully tranquil image, but it''s turned to a grey mush in places.</td>', 'This had the potential to be a wonderfully tranquil image, but it''s turned to a grey mush in places.', '2009-02-01 13:40:18.000000', NULL, 1),
(5232262, 760319, 102712, '<td valign="top">nice idea but I think it would benefit from a better composition, highlighting the subject (or lack of, for that matter) and making the point across better</td>', 'nice idea but I think it would benefit from a better composition, highlighting the subject (or lack of, for that matter) and making the point across better', '2009-02-01 14:37:35.000000', NULL, 1),
(5232267, 759535, 102712, '<td valign="top">Although I always appreciate very little editing, if any at all, I think this shot would have benefitted from darkening and contrasting the sky a bit more. good composition</td>', 'Although I always appreciate very little editing, if any at all, I think this shot would have benefitted from darkening and contrasting the sky a bit more. good composition', '2009-02-01 14:39:53.000000', NULL, 1),
