(5235459, 759977, 63269, '<td valign="top">The composition doesn''t seem very strong here - my eye isn''t sure where to rest.</td>', 'The composition doesn''t seem very strong here - my eye isn''t sure where to rest.', '2009-02-02 15:49:48.000000', NULL, 1),
(5235461, 759159, 63269, '<td valign="top">Interesting lighting.</td>', 'Interesting lighting.', '2009-02-02 15:51:03.000000', NULL, 1),
