(5238161, 760395, 91527, '<td valign="top">I loved this during voting, it should have done a ton better!!  The colors, the pattern of the dress, the processing...all spot-on.  Definitely not a 4.3-worthy photo...!!!!</td>', 'I loved this during voting, it should have done a ton better!!  The colors, the pattern of the dress, the processing...all spot-on.  Definitely not a 4.3-worthy photo...!!!!', '2009-02-04 00:15:10.000000', NULL, 0),
(5238165, 759833, 102559, '<td valign="top">Hi, <br/> <br/>thanks a lot to all of you for your comments. This was my first ever post on dpchallenge and it''s precisely for the comments like these that I think coming here will help me a lot.<br/>As for the challenge, this was a random shot I had taken before and then I realised that I can use it for this challenge. I totally agree that had the legs not been chopped off it might have been better but then there were way too many things in the frame if I tried to retain their entire body. Too long a shutter speed causing the blur!! :(<br/>Also, I agree that focussing should have been a bit more sharp.<br/>Looking forward to hearing from you in future.<br/>Thanks a lot.</td>', 'Hi,  thanks a lot to all of you for your comments. This was my first ever post on dpchallenge and it''s precisely for the comments like these that I think coming here will help me a lot.As for the challenge, this was a random shot I had taken before and then I realised that I can use it for this challenge. I totally agree that had the legs not been chopped off it might have been better but then there were way too many things in the frame if I tried to retain their entire body. Too long a shutter speed causing the blur!! :(Also, I agree that focussing should have been a bit more sharp.Looking forward to hearing from you in future.Thanks a lot.', '2009-02-04 00:16:34.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5238169, 760294, 78132, '<td valign="top">I am one of the 19 that voted 10 on this. Simply incredible shot and from having spent time in the mountains indeed there is complete silence!<br/>Congratulations on this well deserved 1. Place!</td>', 'I am one of the 19 that voted 10 on this. Simply incredible shot and from having spent time in the mountains indeed there is complete silence!Congratulations on this well deserved 1. Place!', '2009-02-04 00:17:16.000000', NULL, 0),
(5238171, 759452, 101492, '<td valign="top">Thanks to all for your comments.  This is only my second challenge attempt so I am excited to have placed so high in the competition.  This shot was taken on a lazy Sunday afternoon as I awoke from a nap and saw my kitty sleeping at the foot of my bed.  It was so tranquil and relaxing.  Perhaps it was more of a sense of serenity than silence, for those who didn''t feel it fit the category.  Sorry for that.  I look forward to learning more about technical aspects of photography so that I can improve and measure up to some of the awesome photographers on the site.</td>', 'Thanks to all for your comments.  This is only my second challenge attempt so I am excited to have placed so high in the competition.  This shot was taken on a lazy Sunday afternoon as I awoke from a nap and saw my kitty sleeping at the foot of my bed.  It was so tranquil and relaxing.  Perhaps it was more of a sense of serenity than silence, for those who didn''t feel it fit the category.  Sorry for that.  I look forward to learning more about technical aspects of photography so that I can improve and measure up to some of the awesome photographers on the site.', '2009-02-04 00:17:50.000000', NULL, 0),
(5238181, 759452, 78132, '<td valign="top">I gave this one a 9 and I have no idea how it would end up in place 14. I was sure you would be in the top 5....</td>', 'I gave this one a 9 and I have no idea how it would end up in place 14. I was sure you would be in the top 5....', '2009-02-04 00:20:59.000000', NULL, 0),
